import java.util.*;

/** prerequisites rows are [course, prerequisite]; duplicates are retained consistently. */
public final class CoursePlan {
    public record Plan(int[] order,int[] level,int[] predecessor) { }
    public static Plan plan(int count,int[][] prerequisites) {
        if(count<0)throw new IllegalArgumentException("negative course count");Objects.requireNonNull(prerequisites,"prerequisites");
        List<List<Integer>> next=new ArrayList<>(count);for(int i=0;i<count;i++)next.add(new ArrayList<>());
        int[] indegree=new int[count],level=new int[count],predecessor=new int[count],order=new int[count];Arrays.fill(predecessor,-1);
        for(int[] edge:prerequisites){if(edge==null||edge.length!=2||edge[0]<0||edge[0]>=count||edge[1]<0||edge[1]>=count)throw new IllegalArgumentException("invalid edge");next.get(edge[1]).add(edge[0]);indegree[edge[0]]++;}
        Deque<Integer> ready=new ArrayDeque<>();for(int i=0;i<count;i++)if(indegree[i]==0)ready.addLast(i);
        int used=0;
        while(!ready.isEmpty()){
            int from=ready.removeFirst();order[used++]=from;
            for(int to:next.get(from)){
                if(level[from]+1>level[to]){level[to]=level[from]+1;predecessor[to]=from;}
                if(--indegree[to]==0)ready.addLast(to);
            }
        }
        if(used!=count)throw new IllegalArgumentException("cycle: no complete course ordering");
        return new Plan(order,level,predecessor);
    }
    static boolean valid(int[] order,int[][] edges){int[] where=new int[order.length];boolean[] seen=new boolean[order.length];for(int i=0;i<order.length;i++){if(order[i]<0||order[i]>=order.length||seen[order[i]])return false;seen[order[i]]=true;where[order[i]]=i;}for(int[] e:edges)if(where[e[1]]>=where[e[0]])return false;return true;}
    static boolean anyPermutation(int[] order,int at,int[][] edges){if(at==order.length)return valid(order,edges);for(int i=at;i<order.length;i++){int t=order[i];order[i]=order[at];order[at]=t;boolean ok=anyPermutation(order,at+1,edges);t=order[i];order[i]=order[at];order[at]=t;if(ok)return true;}return false;}
    static void check(boolean b){if(!b)throw new AssertionError();}
    static void verifyLevels(Plan p,int[][] edges){for(int course:p.order()){int expected=0;for(int[] e:edges)if(e[0]==course)expected=Math.max(expected,p.level()[e[1]]+1);check(p.level()[course]==expected);int parent=p.predecessor()[course];if(expected==0)check(parent==-1);else{check(parent>=0&&p.level()[parent]+1==expected);boolean found=false;for(int[] e:edges)found|=e[0]==course&&e[1]==parent;check(found);}}}
    public static void main(String[] args){
        int dag=0,cyclic=0;
        for(int mask=0;mask<(1<<12);mask++){
            List<int[]> edges=new ArrayList<>();int bit=0;for(int from=0;from<4;from++)for(int to=0;to<4;to++)if(from!=to){if((mask&(1<<bit))!=0)edges.add(new int[]{to,from});bit++;}
            int[][] input=edges.toArray(int[][]::new),before=Arrays.stream(input).map(int[]::clone).toArray(int[][]::new);
            boolean feasible=anyPermutation(new int[]{0,1,2,3},0,input);
            try{Plan p=plan(4,input);check(feasible&&valid(p.order(),input));verifyLevels(p,input);dag++;}catch(IllegalArgumentException ex){check(!feasible);cyclic++;}
            check(Arrays.deepEquals(input,before));
        }
        Plan duplicate=plan(3,new int[][]{{1,0},{1,0},{2,1}});check(Arrays.equals(duplicate.order(),new int[]{0,1,2}));
        check(plan(0,new int[0][]).order().length==0);check(plan(3,new int[0][]).order().length==3);
        for(int[][] bad:new int[][][]{{{0,0}},{{3,0}},{{1}},{{-1,0}}})try{plan(3,bad);throw new AssertionError();}catch(IllegalArgumentException expected){}
        try{plan(-1,new int[0][]);throw new AssertionError();}catch(IllegalArgumentException expected){}
        try{plan(1,null);throw new AssertionError();}catch(NullPointerException expected){}
        System.out.println("PASS all4096 directed4-node graphs: "+dag+" DAG +"+cyclic+" cyclic vs exhaustive permutation oracle;topological order/levels/predecessor;duplicate/isolated/empty/self-cycle/invalid;input preserved");
    }
}

import java.util.*;
public final class ServiceDependencyCycle {
    private static final class Frame {final String node;int edge;Frame(String n){node=n;}}
    /** Input edge service -> dependency. Returned witness is closed (first == last). */
    public static List<String> cycle(Map<String,List<String>> input){
        Objects.requireNonNull(input);Map<String,List<String>> graph=new LinkedHashMap<>();
        for(var e:input.entrySet()){Objects.requireNonNull(e.getKey());Objects.requireNonNull(e.getValue());graph.put(e.getKey(),new ArrayList<>(e.getValue()));}
        List<String> referenced=new ArrayList<>();for(List<String> edges:graph.values())for(String to:edges)referenced.add(Objects.requireNonNull(to));
        for(String s:referenced)graph.putIfAbsent(s,List.of());
        Map<String,Integer> color=new HashMap<>();Map<String,String> parent=new HashMap<>();Deque<Frame> stack=new ArrayDeque<>();
        for(String root:graph.keySet()){
            if(color.getOrDefault(root,0)!=0)continue;
            color.put(root,1);stack.push(new Frame(root));
            while(!stack.isEmpty()){
                Frame f=stack.peek();List<String> edges=graph.get(f.node);
                if(f.edge==edges.size()){color.put(f.node,2);stack.pop();continue;}
                String to=edges.get(f.edge++);int state=color.getOrDefault(to,0);
                if(state==0){parent.put(to,f.node);color.put(to,1);stack.push(new Frame(to));}
                else if(state==1){
                    List<String> path=new ArrayList<>();String p=f.node;path.add(p);
                    while(!p.equals(to)){p=parent.get(p);path.add(p);}
                    Collections.reverse(path);path.add(to);return path;
                }
            }
        }
        return List.of();
    }
    public static void main(String[] args){
        int cyclic=0;
        for(int mask=0;mask<(1<<12);mask++){
            Map<String,List<String>> g=new LinkedHashMap<>();for(int i=0;i<4;i++)g.put("s"+i,new ArrayList<>());
            boolean[][] reach=new boolean[4][4];int bit=0;
            for(int i=0;i<4;i++)for(int j=0;j<4;j++)if(i!=j){if((mask&(1<<bit))!=0){g.get("s"+i).add("s"+j);reach[i][j]=true;}bit++;}
            for(int k=0;k<4;k++)for(int i=0;i<4;i++)for(int j=0;j<4;j++)reach[i][j]|=reach[i][k]&&reach[k][j];
            boolean expected=false;for(int i=0;i<4;i++)expected|=reach[i][i];
            List<String> witness=cycle(g);if(expected==witness.isEmpty())throw new AssertionError();
            if(expected){cyclic++;if(!witness.get(0).equals(witness.get(witness.size()-1)))throw new AssertionError();for(int i=1;i<witness.size();i++)if(!g.get(witness.get(i-1)).contains(witness.get(i)))throw new AssertionError();}
        }
        if(!cycle(Map.of("a",List.of("a"))).equals(List.of("a","a")))throw new AssertionError();
        if(!cycle(Map.of("a",List.of("b","b"))).isEmpty())throw new AssertionError();
        Map<String,List<String>> chain=new LinkedHashMap<>();for(int i=0;i<100000;i++)chain.put("s"+i,i==99999?List.of():List.of("s"+(i+1)));
        if(!cycle(chain).isEmpty())throw new AssertionError();
        System.out.println("PASS all4096 directed four-node graphs vs transitive-closure oracle;"+cyclic+" edge-validated closed witnesses;self/duplicate/referenced-only;100000-depth iterative DFS");
    }
}
